"""
Batch robust trend filtering.  The returned sequence is right-endpoint aligned:
output[i] corresponds to input index i + window_size - 1.
"""
import numpy as np

try:
    from scipy.signal import medfilt, savgol_filter
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False


def _fill_nonfinite(x):
    x = np.asarray(x, dtype=float).ravel().copy()
    finite = np.isfinite(x)
    if finite.all():
        return x
    if not finite.any():
        return np.zeros_like(x)
    ii = np.arange(x.size)
    x[~finite] = np.interp(ii[~finite], ii[finite], x[finite])
    return x


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float).ravel()
    if x.size < window_size:
        raise ValueError("input length must be >= window_size")
    return np.convolve(x, np.ones(window_size) / float(window_size), mode="valid")


def _odd_width(width, n, minimum=5):
    upper = n if n % 2 else n - 1
    if upper < 3:
        return upper
    width = min(int(width), upper)
    if width % 2 == 0:
        width -= 1
    return max(minimum if upper >= minimum else 3, width)


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float).ravel()
    if x.size < window_size:
        raise ValueError("input length must be >= window_size")
    x = _fill_nonfinite(x)
    n = x.size
    if n < 5 or window_size < 3:
        return x[window_size - 1:].copy()

    if _HAVE_SCIPY:
        pre = medfilt(x, kernel_size=5)
        lw = _odd_width(2 * int(window_size) + 1, n)
        sw = _odd_width(int(window_size) + 1, n)
        long_smooth = savgol_filter(pre, lw, min(3, lw - 1), mode="interp")
        short_smooth = savgol_filter(pre, sw, min(2, sw - 1), mode="interp")

        r = x - short_smooth
        noise = 1.4826 * np.median(np.abs(r - np.median(r)))
        noise = max(float(noise), 1e-12)
        disagreement = np.abs(short_smooth - long_smooth)
        gate = np.clip((disagreement - noise) / (2.0 * noise), 0.0, 1.0)

        taper = np.ones(n)
        tail = min(20, n)
        if tail > 1:
            taper[-tail:] = 0.5 + 0.5 * np.sin(
                np.linspace(0.0, np.pi / 2.0, tail)
            )
        smooth = long_smooth + 0.35 * gate * taper * (short_smooth - long_smooth)
    else:
        radius = max(2, min(int(window_size), max(2, (n - 1) // 2)))
        kernel = np.ones(2 * radius + 1) / float(2 * radius + 1)
        smooth = np.convolve(np.pad(x, radius, mode="reflect"), kernel, mode="valid")

    residual = x - smooth
    mad = 1.4826 * np.median(np.abs(residual - np.median(residual)))
    threshold = max(0.03 * np.std(x), 0.50 * mad, 1e-12)

    delta = np.diff(smooth)
    slope_mad = (
        1.4826 * np.median(np.abs(delta - np.median(delta)))
        if delta.size else 0.0
    )
    floor = max(1e-12, 0.02 * threshold, 0.12 * slope_mad)
    signs = np.sign(np.where(np.abs(delta) < floor, 0.0, delta))
    for i in range(1, signs.size):
        if signs[i] == 0:
            signs[i] = signs[i - 1]
    for i in range(signs.size - 2, -1, -1):
        if signs[i] == 0:
            signs[i] = signs[i + 1]

    extrema = [0]
    extrema.extend(
        i + 1 for i in range(max(0, signs.size - 1))
        if signs[i] * signs[i + 1] < 0
    )
    if n > 1:
        extrema.append(n - 1)

    kept = []
    for point in extrema:
        kept.append(point)
        while len(kept) >= 3:
            a, b, c = kept[-3:]
            if min(abs(smooth[b] - smooth[a]), abs(smooth[c] - smooth[b])) < 1.5 * threshold:
                kept.pop(-2)
            else:
                break

    stabilized = smooth.copy()
    for left, right in zip(kept[:-1], kept[1:]):
        values = smooth[left:right + 1]
        descending = values[-1] < values[0]
        work = -values if descending else values

        means, weights, starts = [], [], []
        for j, value in enumerate(work):
            means.append(float(value))
            weights.append(1.0)
            starts.append(j)
            while len(means) >= 2 and means[-2] > means[-1]:
                w = weights[-2] + weights[-1]
                means[-2] = (means[-2] * weights[-2] + means[-1] * weights[-1]) / w
                weights[-2] = w
                means.pop()
                weights.pop()
                starts.pop()

        projected = np.empty_like(work)
        for j, start in enumerate(starts):
            stop = starts[j + 1] if j + 1 < len(starts) else work.size
            projected[start:stop] = means[j]
        if descending:
            projected = -projected

        lo, hi = sorted((smooth[left], smooth[right]))
        projected = np.clip(projected, lo, hi)
        projected = (
            np.minimum.accumulate(projected)
            if descending else np.maximum.accumulate(projected)
        )
        projected[0], projected[-1] = smooth[left], smooth[right]
        stabilized[left:right + 1] = projected

    return np.asarray(stabilized[window_size - 1:], dtype=float)


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
        + 0.1 * t * np.sin(0.2 * t)
    )
    clean += np.cumsum(rng.randn(length) * 0.05)
    return clean + rng.normal(0, noise_level, length), clean


def run_signal_processing(
    noisy_signal=None, signal_length=1000, noise_level=0.3, window_size=20
):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level
        )
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float).ravel()
        clean_signal = None

    filtered = process_signal(noisy_signal, window_size, "enhanced")
    required = len(noisy_signal) - window_size + 1
    filtered = np.asarray(filtered[:required], dtype=float)

    if clean_signal is None:
        return {
            "filtered_signal": filtered,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered),
        }

    clean = clean_signal[window_size - 1:window_size - 1 + len(filtered)]
    noisy = noisy_signal[window_size - 1:window_size - 1 + len(filtered)]
    correlation = np.corrcoef(filtered, clean)[0, 1] if len(filtered) > 1 else 0
    before = np.var(noisy - clean)
    after = np.var(filtered - clean)
    return {
        "filtered_signal": filtered,
        "clean_signal": clean,
        "noisy_signal": noisy,
        "correlation": correlation,
        "noise_reduction": (before - after) / before if before > 0 else 0,
        "signal_length": len(filtered),
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

